    var priority = resolveStoryPriority(entry, params, config);
    var issueTypeName = getJiraIssueTypeName(config);

    var fieldsJson = {
        summary: summary,
        description: description,
        issuetype: { name: issueTypeName },
        parent: { key: resolvedParentKey }
