function moveFailedTcToRework(tracker, ticketKey, jiraConfig) {
    tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
    console.log('🔧 Moved', ticketKey, 'to', jiraConfig.statuses.IN_REWORK);
