                    bugLinked = true;
                    comment = 'h3. 🐛 New Bug Created\n\n' +
                        'Created: *' + bugKey + '*\n' +
                        '*Summary*: ' + summary + '\n\n' +
                        (decision.reason ? '_' + decision.reason + '_' : '');
