            try {
                // gh-916: PASSED can be tag-only (restricted ADO workflows) — stage-label fallback.
                var passMove = tracker.moveToStatusOrMark(ticketKey, jiraConfig.statuses.PASSED, 'PASSED');
                if (passMove.moved || passMove.marked) {
