                }
            } catch (e) {
                console.warn('Failed to move to Passed:', e);
            }
            try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
            if (smTriggerLabel) {
                try { tracker.removeLabel(ticketKey, smTriggerLabel); } catch (e) {}
