        lines.push('*Failed:*');
        failed.forEach(function(item) {
            lines.push('* ' + item.summary + ' - ' + item.error);
        });
        lines.push('');
    }

    lines.push('*Total Processed:* ' + (created.length + reused.length));
    return lines.join('\n');
}

