        var b2fMove = ctx.tracker.moveToStatusOrMark(ctx.ticketKey, ctx.jiraConfig.statuses.BUG_TO_FIX, 'BUG_TO_FIX');
        if (b2fMove.moved || b2fMove.marked) {
