        if (passMove.moved || passMove.marked) {
            console.log('✅ Tests pass — moved', ctx.ticketKey, 'to', ctx.jiraConfig.statuses.PASSED);
        }
    } catch (e) {
        console.warn('Failed to move to Passed:', e);
